import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.add('a'), { ok: false, reason: 'no such cart' });
  assert.equal((await h.open('a')).ok, true);
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, true);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map(({ id, ...m }) => m), [{ from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } }]);
  await h.deliver(msgs[0].id);
  assert.equal((await h.cart('a'))!.status, 'reserving');
  await h.deliver((await h.inFlight())[0].id);
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  assert.equal(await h.cart('zz'), null);
});

test('out of stock, decline, cancelling', async () => {
  const h = await createHost();
  for (const c of ['a', 'b', 'c']) { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); }
  assert.equal((await h.cancel('c')).ok, true);
  assert.equal((await h.cart('c'))!.status, 'cancelling');
  await h.declineCards();
  assert.equal((await h.declineCards()).ok, false);
  await h.deliverAll();
  const statuses = await Promise.all(['a', 'b', 'c'].map(async (c) => (await h.cart(c))!.status));
  assert.equal(statuses[2], 'cancelled');
  assert.ok(statuses.includes('failed'));
  const d = statuses[0] === 'declined' ? 'a' : 'b';
  assert.equal((await h.cart(d))!.status, 'declined');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[cmd](d)).ok, false);
  // retry while still declining -> declined again
  assert.equal((await h.retry(d)).ok, true);
  assert.equal((await h.cart(d))!.status, 'paying');
  assert.equal((await h.retry(d)).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart(d))!.status, 'declined');
  assert.equal((await h.abandon(d)).ok, true);
  assert.equal((await h.abandon(d)).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart(d))!.status, 'failed');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

test('retry succeeds', async () => {
  const h = await createHost();
  await h.declineCards();
  await h.open('a'); await h.add('a'); await h.checkout('a'); await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'declined');
  await h.acceptCards();
  await h.retry('a'); await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  assert.deepEqual(await h.payments(), { charged: 1, declining: false });
});

test('returns', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  await h.checkout('a'); await h.deliverAll();
  assert.equal((await h.returnCart('a')).ok, true);
  assert.equal((await h.cart('a'))!.status, 'returned');
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.add('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  const actions = (await h.inFlight()).map((m) => `${m.to}:${m.action}:${JSON.stringify(m.data)}`).sort();
  assert.deepEqual(actions, ['inventory:Release:{"qty":1}', 'payments:Refund:{"amount":1}']);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
});

test('charge limit', async () => {
  const h = await createHost();
  // only 2 units of stock, so limit 4 is hard to hit; just check accept toggles
  assert.equal((await h.acceptCards()).ok, false);
  assert.equal((await h.declineCards()).ok, true);
  assert.equal((await h.acceptCards()).ok, true);
});
